  "implementation": "def solve(case):
    import math
    if not isinstance(case, dict) or 'payload' not in case:
        raise ValueError('Invalid case structure')
    payload = case['payload']
    required = ['sentence_vectors', 'query_vector', 'context_weight']
    for key in required:
        if key not in payload:
            raise ValueError(f'Missing required field: {key}')
    sentence_vectors = payload['sentence_vectors']
    query_vector = payload['query_vector']
    context_weight = payload['context_weight']
    if not isinstance(sentence_vectors, list) or not all(isinstance(v, list) for v in sentence_vectors):
        raise ValueError('sentence_vectors must be a list of lists')
    if not isinstance(query_vector, list) or len(query_vector) == 0:
        raise ValueError('query_vector must be a non-empty list')
    dim = len(query_vector)
    for sv in sentence_vectors:
        if len(sv) != dim:
            raise ValueError('All sentence vectors must have the same dimension as query_vector')
    def cosine_sim(a, b):
        dot = sum(x*y for x,y in zip(a,b))
        norm_a = math.sqrt(sum(x*x for x in a))
        norm_b = math.sqrt(sum(x*x for x in b))
        if norm_a == 0.0 or norm_b == 0.0:
            return 0.0
        return dot / (norm_a * norm_b)
    n = len(sentence_vectors)
    sims = [cosine_sim(sv, query_vector) for sv in sentence_vectors]
    neighbor_avgs = []
    for i in range(n):
        neighbor_sims = []
        if i > 0:
            neighbor_sims.append(sims[i-1])
        if i < n-1:
            neighbor_sims.append(sims[i+1])
        if neighbor_sims:
            avg = sum(neighbor_sims) / len(neighbor_sims)
        else:
            avg = 0.0
        neighbor_avgs.append(avg)
    scores = [(1.0 - context_weight) * sims[i] + context_weight * neighbor_avgs[i] for i in range(n)]
    rounded_scores = [round(s, 4) for s in scores]
    indexed = list(enumerate(rounded_scores))
    ranked = sorted(indexed, key=lambda x: (-x[1], x[0]))
    ranks = [0] * n
    for rank, (idx, _) in enumerate(ranked, start=1):
        ranks[idx] = rank
    return {
        'scores': rounded_scores,
        'ranks': ranks
    }"
